function decodeBase64(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

function encodeBase64Url(value) {
  const bytes = typeof value === 'string' ? new TextEncoder().encode(value) : value;
  let binary = '';
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replaceAll('+', '-').replaceAll('/', '_').replace(/=+$/, '');
}

function decodeBase64Url(value) {
  const normalized = value.replaceAll('-', '+').replaceAll('_', '/');
  return new TextDecoder().decode(decodeBase64(normalized + '='.repeat((4 - normalized.length % 4) % 4)));
}

function decodeBase64UrlBytes(value) {
  const normalized = value.replaceAll('-', '+').replaceAll('_', '/');
  return decodeBase64(normalized + '='.repeat((4 - normalized.length % 4) % 4));
}

function secureHeaders(extra = {}) {
  return new Headers({
    'x-content-type-options': 'nosniff',
    'x-frame-options': 'DENY',
    'referrer-policy': 'no-referrer',
    'content-security-policy': "default-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'; object-src 'none'; connect-src 'self'; img-src 'self' data:; media-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'",
    'permissions-policy': 'camera=(), geolocation=(), microphone=()',
    'cross-origin-opener-policy': 'same-origin',
    'cross-origin-resource-policy': 'same-origin',
    'strict-transport-security': 'max-age=31536000; includeSubDomains',
    ...extra,
  });
}

function textResponse(body, status = 200, extra = {}) {
  return new Response(body, { status, headers: secureHeaders({ 'content-type': 'text/plain; charset=utf-8', ...extra }) });
}

function jsonResponse(body, status = 200, extra = {}) {
  return new Response(JSON.stringify(body, null, 2), { status, headers: secureHeaders({ 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', ...extra }) });
}

function notFound(pathname) {
  return textResponse('404 // ROUTE NOT FOUND\n' + pathname + '\n', 404);
}

function redirect(location) {
  return new Response(null, { status: 308, headers: secureHeaders({ location }) });
}

async function hmac(value) {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(hydraRuntime.session_secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const signature = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(value));
  return encodeBase64Url(new Uint8Array(signature));
}

async function verifyHmac(value, encodedSignature) {
  try {
    const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(hydraRuntime.session_secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['verify']);
    return await crypto.subtle.verify('HMAC', key, decodeBase64UrlBytes(encodedSignature), new TextEncoder().encode(value));
  } catch {
    return false;
  }
}

function sessionCookie(request) {
  const cookie = request.headers.get('cookie') || '';
  const match = cookie.match(/(?:^|;\s*)hydra_session=([^;]+)/);
  return match?.[1] || null;
}

async function readSession(request) {
  const token = sessionCookie(request);
  if (!token) return null;
  const separator = token.lastIndexOf('.');
  if (separator < 1) return null;
  const payload = token.slice(0, separator);
  const signature = token.slice(separator + 1);
  if (!await verifyHmac(payload, signature)) return null;
  try {
    const session = JSON.parse(decodeBase64Url(payload));
    if (session.exp < Math.floor(Date.now() / 1000)) return null;
    return session;
  } catch {
    return null;
  }
}

async function authenticate(request) {
  let credentials;
  try {
    credentials = await request.json();
  } catch {
    return jsonResponse({ error: 'MALFORMED CREDENTIAL ENVELOPE' }, 400);
  }
  const operative = String(credentials?.operative || '').trim().toLowerCase();
  const passcode = String(credentials?.passcode || '');
  if (operative !== hydraRuntime.operative || passcode !== hydraRuntime.passcode) {
    return jsonResponse({ authenticated: false, error: 'CREDENTIAL PAIR REJECTED' }, 401);
  }
  const session = { sub: hydraRuntime.operative.toUpperCase(), role: 'OPERATIVE', exp: Math.floor(Date.now() / 1000) + 1800 };
  const payload = encodeBase64Url(JSON.stringify(session));
  const token = payload + '.' + await hmac(payload);
  return jsonResponse(
    { authenticated: true, operative: session.sub, role: session.role },
    200,
    {
      'set-cookie': 'hydra_session=' + token + '; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=1800',
      'x-deprecated-api': hydraRuntime.deprecated_api,
    },
  );
}

