function hydraPublicRoute(pathname) {
  if (pathname === '/robots.txt') return textResponse('User-agent: *\nDisallow: /maintenance/\n');
  if (pathname === '/maintenance') return redirect('/maintenance/');
  if (pathname === '/maintenance/') return maintenanceIndex();
  if (pathname === '/maintenance/operator.txt') return textResponse([
    'BLACKSITE-04 / OPERATOR ROTATION',
    'OPERATIVE_ID=' + hydraRuntime.operative.toUpperCase(),
    'PASSCODE_COMPONENT=WITHHELD',
    'PAIRING_NOTE=Credential envelope continues in rotation.log.',
  ].join('\n') + '\n');
  if (pathname === '/maintenance/rotation.log') return textResponse([
    '2026-08-28T03:14:00Z // ROTATION ACCEPTED',
    'PASSCODE_B64=' + hydraRuntime.passcode_b64,
    'TRANSPORT_NOTE=Passcode field uses standard Base64 transport encoding.',
  ].join('\n') + '\n');
  if (pathname === '/maintenance/README.txt') return textResponse([
    'BLACKSITE-04 // MAINTENANCE HANDOFF',
    'The ops cache is a perimeter canary, not an archive object.',
    'After a successful credential exchange, inspect the response headers for the retired interface.',
    'Legacy logistics records expose archive relationships by numeric transfer ID.',
    'Archive payloads inherit their byte mask from the associated transfer checksum.',
    'Automated model-restoration plates belong to perimeter recovery, not the numbered object archive.',
  ].join('\n') + '\n');
  if (pathname === '/maintenance/ops-cache.json') {
    const cache = assets['/challenges/hydra/ops-cache.json'];
    if (!cache) return notFound(pathname);
    return new Response(decodeBase64(cache.body), { status: 200, headers: secureHeaders({ 'content-type': cache.type, 'cache-control': 'no-store' }) });
  }
  if (pathname === '/maintenance/model-restoration-order.svg') {
    const plate = assets['/challenges/hydra/model-restoration-order.svg'];
    if (!plate) return notFound(pathname);
    return new Response(decodeBase64(plate.body), { status: 200, headers: secureHeaders({ 'content-type': plate.type, 'cache-control': 'no-store' }) });
  }
  return null;
}

function hydraApiRoute(pathname) {
  if (pathname === '/api/v0') return redirect('/api/v0/');
  if (pathname === '/api/v0/') return jsonResponse({ version: 'v0', status: '/api/v0/status', resources: ['/api/v0/logistics/'] });
  if (pathname === '/api/v0/status') return jsonResponse({ node: 'BLACKSITE-04', role: 'OPERATIVE', legacy_resolver: 'ENABLED', logistics_index: '/api/v0/logistics/' });
  if (pathname === '/api/v0/logistics') return redirect('/api/v0/logistics/');
  if (pathname === '/api/v0/logistics/') return jsonResponse({ resource: 'transfers', route: '/api/v0/logistics/transfers/{id}', indexed_transfers: [4401, 7714] });
  if (pathname === '/api/v0/logistics/transfers/4401') return jsonResponse({ id: 4401, origin: 'SITE-09', contents: 'POWER CONDITIONER', status: 'DELIVERED', checksum: '11-2A-02-39', archive_object: null });
  if (pathname === '/api/v0/logistics/transfers/7714') return jsonResponse({ ...hydraRuntime.transfer, archive_route: '/api/v0/archive/7714' });
  if (pathname === '/api/v0/archive/7714') return jsonResponse(hydraRuntime.archive);
  if (pathname === '/downloads/archive-7714.json') return jsonResponse(hydraRuntime.archive, 200, { 'content-disposition': 'attachment; filename="archive-7714.json"' });
  return null;
}

function assetResponse(asset, request, url) {
  const headers = secureHeaders({ 'content-type': asset.type });
  if (asset.type.startsWith('text/html')) {
    const html = new TextDecoder().decode(decodeBase64(asset.body)).replaceAll('__SITE_ORIGIN__', url.origin);
    headers.set('cache-control', 'no-cache');
    return new Response(request.method === 'HEAD' ? null : html, { status: 200, headers });
  }
  headers.set('cache-control', url.pathname.startsWith('/assets/') ? 'public, max-age=31536000, immutable' : 'public, max-age=300');
  return new Response(request.method === 'HEAD' ? null : decodeBase64(asset.body), { status: 200, headers });
}

export default {
  async fetch(request) {
    const url = new URL(request.url);

    if (siteChallenge === 'hydra') {
      if (request.method === 'POST' && url.pathname === '/auth/session') return authenticate(request);
      if (request.method === 'GET' && url.pathname === '/auth/session') {
        const session = await readSession(request);
        return session ? jsonResponse({ authenticated: true, operative: session.sub, role: session.role }) : jsonResponse({ authenticated: false }, 401);
      }

      if (request.method === 'GET' || request.method === 'HEAD') {
        const publicResponse = hydraPublicRoute(url.pathname);
        if (publicResponse) return request.method === 'HEAD' ? new Response(null, { status: publicResponse.status, headers: publicResponse.headers }) : publicResponse;

        if (url.pathname.startsWith('/api/') || url.pathname.startsWith('/downloads/')) {
          const session = await readSession(request);
          if (!session) return jsonResponse({ error: 'AUTHENTICATION REQUIRED' }, 401);
          const apiResponse = hydraApiRoute(url.pathname);
          if (!apiResponse) return notFound(url.pathname);
          return request.method === 'HEAD' ? new Response(null, { status: apiResponse.status, headers: apiResponse.headers }) : apiResponse;
        }

        const requestedAsset = assets[url.pathname];
        if (requestedAsset) return assetResponse(requestedAsset, request, url);
        if (url.pathname === '/' || url.pathname === '/hydra-blacksite') return assetResponse(assets['/index.html'], request, url);
      }

      return notFound(url.pathname);
    }

    const requestedAsset = assets[url.pathname];
    const isFileRequest = url.pathname.split('/').pop()?.includes('.') ?? false;
    const asset = requestedAsset || (request.method === 'GET' && !isFileRequest ? assets['/index.html'] : null);
    if (!asset) return notFound(url.pathname);
    return assetResponse(asset, request, url);
  },
};
